'use client'

import { useEffect, useMemo, useState, type FormEvent } from 'react'

type WordCard = { id: string; word: string; meaning: string; example: string; clozeSentence?: string; verbBase?: string; verbAnswer?: string[]; hint?: string }
type Mode = 'idle' | 'choice' | 'typing' | 'sentences' | 'verb'
type SelectionMode = 'manual' | 'random'
const STORAGE_KEY = 'kotoba-en-cards-v1'
const WORD_PACK_MARKER_KEY = 'kotoba-en-wildlife-pack-v1-installed'
const starterWords: Omit<WordCard, 'id'>[] = [
  { word: 'to unwind', meaning: 'thư giãn, xả hơi', example: 'I like to unwind with a book after work.' },
  { word: "to refresh one's mind", meaning: 'làm đầu óc tỉnh táo, sảng khoái lại', example: 'A short walk outside can refresh your mind.' },
  { word: 'passion', meaning: 'niềm đam mê', example: 'Her passion for wildlife conservation inspired her career.' },
  { word: 'leisure time', meaning: 'thời gian rảnh', example: 'He spends his leisure time hiking in the hills.' },
  { word: 'extinct', meaning: 'tuyệt chủng', example: 'The dodo became extinct in the seventeenth century.' },
  { word: 'conservation', meaning: 'sự bảo tồn', example: 'The reserve funds conservation projects to protect endangered animals.' },
  { word: 'reintroduction', meaning: 'sự tái thả, tái du nhập', example: 'The reintroduction of wolves helped restore the ecosystem.' },
  { word: 'habitat', meaning: 'môi trường sống', example: 'Wetlands provide a vital habitat for many bird species.' },
  { word: 'dam', meaning: 'đập', example: 'The new dam supplies water to nearby farms.' },
  { word: 'species', meaning: 'loài', example: 'This species can survive in very cold conditions.' },
]
const normalizeWord = (word: string) => word.toLocaleLowerCase().trim().replace(/\s+/g, ' ')
const clean = (text: string) => text.toLocaleLowerCase().replace(/[.,!?;:]/g, '').replace(/\s+/g, ' ').trim()
const cleanSentence = (text: string) => text.toLocaleLowerCase().replace(/\s+([,.!?;:])/g, '$1').replace(/[.,!?;:]/g, '').replace(/\s+/g, ' ').trim()
const makeId = () => typeof crypto !== 'undefined' && 'randomUUID' in crypto ? crypto.randomUUID() : `${Date.now()}-${Math.random()}`

const parseCsv = (text: string): string[][] => {
  const rows: string[][] = []
  let row: string[] = [], cell = '', quoted = false
  for (let i = 0; i < text.length; i += 1) {
    const char = text[i]
    if (char === '"' && quoted && text[i + 1] === '"') { cell += '"'; i += 1 }
    else if (char === '"') quoted = !quoted
    else if (char === ',' && !quoted) { row.push(cell); cell = '' }
    else if ((char === '\n' || char === '\r') && !quoted) {
      if (char === '\r' && text[i + 1] === '\n') i += 1
      row.push(cell); if (row.some((item) => item.trim())) rows.push(row)
      row = []; cell = ''
    } else cell += char
  }
  if (quoted) throw new Error('The CSV has an unclosed quote. Check quoted cells and try again.')
  row.push(cell); if (row.some((item) => item.trim())) rows.push(row)
  return rows
}

const normalizeRows = (rows: Record<string, unknown>[]) => {
  const cards: WordCard[] = [], errors: string[] = []
  rows.forEach((source, index) => {
    const rowNumber = index + 1
    const stringFields = ['word', 'meaning', 'example', 'clozesentence', 'verbbase', 'hint']
    const invalidFields = stringFields.filter((key) => source[key] != null && typeof source[key] !== 'string')
    for (const key of ['verbanswer', 'verbanswers']) {
      const answerValue = source[key]
      if (answerValue == null) continue
      if (typeof answerValue !== 'string' && !Array.isArray(answerValue)) invalidFields.push(key)
      else if (Array.isArray(answerValue) && answerValue.some((item) => typeof item !== 'string')) invalidFields.push(key)
    }
    if (invalidFields.length) {
      errors.push(`Row ${rowNumber}: ${invalidFields.join(', ')} must be strings${invalidFields.some((key) => key === 'verbanswer' || key === 'verbanswers') ? ' (or an array of strings for verbAnswer)' : ''}.`)
      return
    }
    const value = (key: string) => (typeof source[key] === 'string' ? source[key] as string : '').trim()
    const word = value('word'), meaning = value('meaning'), example = value('example')
    const clozeSentence = value('clozesentence')
    const verbBase = value('verbbase')
    const answerSource = source['verbanswer'] ?? source['verbanswers'] ?? ''
    const verbAnswer = Array.isArray(answerSource)
      ? answerSource.map((answer) => (answer as string).trim()).filter(Boolean)
      : String(answerSource).split('|').map((answer) => answer.trim()).filter(Boolean)
    const hint = value('hint')
    if (!word || !meaning) { errors.push(`Row ${rowNumber}: word and meaning are required.`); return }
    const hasClozeData = !!(clozeSentence || verbBase || verbAnswer.length)
    if (hasClozeData && (!clozeSentence.includes('___') || !verbBase || !verbAnswer.length)) {
      errors.push(`Row ${rowNumber} (${word}): clozeSentence must include ___, with verbBase and at least one verbAnswer.`); return
    }
    cards.push({ id: makeId(), word, meaning, example, ...(hasClozeData ? { clozeSentence, verbBase, verbAnswer, hint } : {}) })
  })
  return { cards, errors }
}

const importFile = async (file: File) => {
  const text = await file.text()
  let rows: Record<string, unknown>[]
  if (file.name.toLowerCase().endsWith('.csv') || file.type === 'text/csv') {
    const [headerRow, ...dataRows] = parseCsv(text)
    if (!headerRow?.length) throw new Error('The CSV is empty. Add a header row and at least one word.')
    const headers = headerRow.map((header) => header.replace(/^\uFEFF/, '').trim().toLowerCase())
    if (!headers.includes('word') || !headers.includes('meaning')) throw new Error('CSV headers must include word and meaning.')
    rows = dataRows.map((values) => Object.fromEntries(headers.map((header, i) => [header, values[i] ?? ''])))
  } else {
    const parsed: unknown = JSON.parse(text)
    const list = Array.isArray(parsed) ? parsed : parsed && typeof parsed === 'object' && 'cards' in parsed && Array.isArray((parsed as { cards: unknown }).cards) ? (parsed as { cards: unknown[] }).cards : null
    if (!list) throw new Error('JSON must be an array of word objects, or an object with a cards array.')
    rows = list.map((item) => {
      if (!item || typeof item !== 'object' || Array.isArray(item)) return {}
      return Object.fromEntries(Object.entries(item).map(([key, value]) => [key.toLowerCase(), value]))
    })
  }
  return normalizeRows(rows)
}

const downloadTemplate = (format: 'json' | 'csv') => {
  const sample = [{ word: 'go', meaning: 'move from one place to another', example: 'I go to work by bus.', clozeSentence: 'Yesterday, I ___ to work by bus.', verbBase: 'go', verbAnswer: ['went'], hint: 'Simple past' }]
  const content = format === 'json'
    ? JSON.stringify(sample, null, 2)
    : 'word,meaning,example,clozeSentence,verbBase,verbAnswer,hint\n"go","move from one place to another","I go to work by bus.","Yesterday, I ___ to work by bus.","go","went","Simple past"'
  const blob = new Blob([content], { type: format === 'json' ? 'application/json' : 'text/csv' })
  const url = URL.createObjectURL(blob); const link = document.createElement('a')
  link.href = url; link.download = `wordcraft-template.${format}`; link.click(); URL.revokeObjectURL(url)
}

export default function App() {
  const [cards, setCards] = useState<WordCard[]>([])
  const [loaded, setLoaded] = useState(false)
  const [storageReady, setStorageReady] = useState(false)
  const [mode, setMode] = useState<Mode>('idle')
  const [selected, setSelected] = useState<string[]>([])
  const [selectionMode, setSelectionMode] = useState<SelectionMode>('manual')
  const [customCount, setCustomCount] = useState('')
  const [selectionMessage, setSelectionMessage] = useState('')
  const [importMessage, setImportMessage] = useState('')
  const [importError, setImportError] = useState('')
  const [questionIndex, setQuestionIndex] = useState(0)
  const [answer, setAnswer] = useState('')
  const [feedback, setFeedback] = useState<boolean | null>(null)
  const [score, setScore] = useState(0)
  const [newWord, setNewWord] = useState('')
  const [newMeaning, setNewMeaning] = useState('')
  const [newExample, setNewExample] = useState('')
  const [sentenceTokens, setSentenceTokens] = useState<string[]>([])
  const [sentenceAnswer, setSentenceAnswer] = useState<string[]>([])
  const [sentenceWord, setSentenceWord] = useState('')
  const [sentenceExpected, setSentenceExpected] = useState('')
  const [sentenceCheck, setSentenceCheck] = useState<boolean | null>(null)
  const [choiceOrder, setChoiceOrder] = useState<string[]>([])

  useEffect(() => {
    let existingCards: WordCard[] = []
    let canPersist = true
    try {
      const raw = localStorage.getItem(STORAGE_KEY)
      if (raw) {
        const parsed: unknown = JSON.parse(raw)
        if (Array.isArray(parsed)) existingCards = parsed as WordCard[]
        else canPersist = false
      }
    } catch { canPersist = false }
    let mergedCards = existingCards
    try {
      if (canPersist && localStorage.getItem(WORD_PACK_MARKER_KEY) !== 'v1') {
        const existingWords = new Set(existingCards.flatMap((card) => typeof card.word === 'string' ? [normalizeWord(card.word)] : []))
        const missingWords = starterWords.filter((card) => !existingWords.has(normalizeWord(card.word)))
          .map((card) => ({ ...card, id: makeId() }))
        mergedCards = [...existingCards, ...missingWords]
        localStorage.setItem(STORAGE_KEY, JSON.stringify(mergedCards))
        localStorage.setItem(WORD_PACK_MARKER_KEY, 'v1')
      }
    } catch { /* Keep current cards available; a failed migration is safe to retry. */ }
    setCards(mergedCards)
    setStorageReady(canPersist)
    setLoaded(true)
  }, [])
  useEffect(() => { if (loaded && storageReady) { try { localStorage.setItem(STORAGE_KEY, JSON.stringify(cards)) } catch { /* Session-only fallback. */ } } }, [cards, loaded, storageReady])

  const activeCards = useMemo(() => cards.filter((card) => selected.includes(card.id)), [cards, selected])
  const verbCards = useMemo(() => activeCards.filter((card) => card.clozeSentence?.includes('___') && card.verbBase?.trim() && card.verbAnswer?.length), [activeCards])
  const current = activeCards[questionIndex]
  const currentVerb = verbCards[questionIndex]
  const addWord = (event: FormEvent) => {
    event.preventDefault()
    if (!newWord.trim() || !newMeaning.trim()) return
    const card: WordCard = { id: makeId(), word: newWord.trim(), meaning: newMeaning.trim(), example: newExample.trim() }
    setCards((items) => [card, ...items]); setSelected((items) => [...items, card.id])
    setNewWord(''); setNewMeaning(''); setNewExample('')
  }
  const handleImport = async (file?: File) => {
    if (!file) return
    setImportError(''); setImportMessage('')
    if (!/\.(json|csv)$/i.test(file.name)) { setImportError('Choose a .json or .csv vocabulary file.'); return }
    try {
      const result = await importFile(file)
      if (result.errors.length) { setImportError(`Nothing was imported. Fix these rows and try again:\n${result.errors.join('\n')}`); return }
      if (!result.cards.length) { setImportError('No vocabulary rows found. Add at least one word and meaning.'); return }
      setCards((items) => [...result.cards, ...items])
      setSelected((items) => [...new Set([...result.cards.map((card) => card.id), ...items])])
      setImportMessage(`Imported ${result.cards.length} word${result.cards.length === 1 ? '' : 's'} and selected them for practice.`)
    } catch (error) {
      setImportError(error instanceof Error ? error.message : 'The file could not be read. Check its format and try again.')
    }
  }
  const sampleRandom = (requested: number) => {
    if (!Number.isInteger(requested) || requested < 1) { setSelectionMessage('Enter a whole number greater than zero.'); return }
    if (!cards.length) { setSelectionMessage('Add or import some English words before starting a random deck.'); return }
    const shuffled = [...cards].sort(() => Math.random() - 0.5)
    const sample = shuffled.slice(0, Math.min(requested, cards.length))
    setSelected(sample.map((card) => card.id)); setSelectionMode('random')
    setSelectionMessage(requested > cards.length ? `Your deck has ${cards.length} words, so all ${cards.length} are selected.` : `Randomly selected ${sample.length} of ${cards.length} words.`)
  }
  const prepareChoices = (index: number) => {
    const deck = cards.filter((card) => selected.includes(card.id))
    const target = deck[index]
    if (!target) { setChoiceOrder([]); return }
    const choices = [target, ...deck.filter((card) => card.id !== target.id).sort(() => Math.random() - 0.5).slice(0, 3)]
    setChoiceOrder(choices.sort(() => Math.random() - 0.5).map((card) => card.id))
  }
  const begin = (nextMode: Mode) => {
    setMode(nextMode); setQuestionIndex(0); setScore(0); setAnswer(''); setFeedback(null); setSentenceAnswer([])
    if (nextMode === 'sentences') prepareSentence(0)
    if (nextMode === 'choice') prepareChoices(0)
  }
  const prepareSentence = (index: number) => {
    const selectedCards = cards.filter((card) => selected.includes(card.id) && card.example.trim())
    const source = selectedCards[index % Math.max(selectedCards.length, 1)]
    const example = source?.example || 'Write an example sentence for this word'
    const words = example.match(/[\w’'-]+|[^\s\w]/g) ?? []
    setSentenceWord(source?.word ?? '')
    setSentenceExpected(example)
    setSentenceCheck(null)
    setSentenceTokens([...words].sort(() => Math.random() - 0.5)); setSentenceAnswer([])
  }
  const check = (value = answer) => {
    if (!current || !value.trim()) return
    const correct = clean(value) === clean(current.meaning)
    setAnswer(value)
    setFeedback(correct); if (correct) setScore((n) => n + 1)
  }
  const checkVerb = () => {
    if (!currentVerb || !answer.trim()) return
    const expected = currentVerb.verbAnswer ?? []
    const correct = expected.some((form) => clean(answer) === clean(form))
    setFeedback(correct); if (correct) setScore((n) => n + 1)
  }
  const next = () => {
    const nextIndex = questionIndex + 1
    setQuestionIndex(nextIndex); setAnswer(''); setFeedback(null)
    if (mode === 'sentences') prepareSentence(questionIndex + 1)
    if (mode === 'choice') prepareChoices(nextIndex)
  }
  const choose = (tokenIndex: number) => {
    setSentenceAnswer((items) => [...items, sentenceTokens[tokenIndex]])
    setSentenceTokens((items) => items.filter((_, i) => i !== tokenIndex))
  }
  const resetSentence = () => {
    setSentenceTokens([...sentenceTokens, ...sentenceAnswer].sort(() => Math.random() - 0.5)); setSentenceAnswer([]); setSentenceCheck(null)
  }

  return <div className="shell">
    <header className="topbar"><a className="logo" href="#home" onClick={() => setMode('idle')}>word<span>craft</span></a><span className="local-note">Your vocabulary stays on this device</span></header>
    <main id="home">
      <section className="welcome"><p className="eyebrow">A small daily practice</p><h1>Make every new word<br />feel like yours.</h1><p className="subhead">Build a personal English deck, then practise meaning and sentence order in the way that works for you.</p></section>
      <section className="language-grid" aria-label="Choose a language">
        <article className="language-card english"><div className="language-icon">EN</div><div><p className="eyebrow">Your active space</p><h2>English</h2><p>Learn vocabulary, check meanings, and build sentences from words you choose.</p></div><span className="available">Available now ↗</span></article>
        <article className="language-card japanese" aria-disabled="true"><div className="language-icon">日</div><div><p className="eyebrow">Coming soon</p><h2>Japanese</h2><p>This learning space is temporarily closed while it is being prepared.</p></div><span className="locked">Temporarily unavailable</span></article>
      </section>

      <section className="workspace" aria-labelledby="library-title">
        <div className="section-title"><div><p className="eyebrow">English learning space</p><h2 id="library-title">Your word library <span>{cards.length}</span></h2></div><p>Select the words you want to practise. Sentence exercises use their example sentences.</p></div>
        <form className="add-form" onSubmit={addWord}>
          <label>Word<input value={newWord} onChange={(e) => setNewWord(e.target.value)} placeholder="e.g. resilient" /></label>
          <label>Meaning<input value={newMeaning} onChange={(e) => setNewMeaning(e.target.value)} placeholder="e.g. able to recover quickly" /></label>
          <label className="example-field">Example sentence <small>needed for sentence-building practice</small><input value={newExample} onChange={(e) => setNewExample(e.target.value)} placeholder="She stayed resilient through the challenge." /></label>
          <button className="button dark" type="submit" disabled={!newWord.trim() || !newMeaning.trim()}>Add word <span>＋</span></button>
        </form>
        <details className="import-panel"><summary>Import a deck from JSON or CSV</summary><div className="import-content"><p>Required fields: <code>word</code> and <code>meaning</code>. Add <code>example</code> for sentence ordering. Verb practice needs all three fields: <code>clozeSentence</code> containing <code>___</code>, <code>verbBase</code>, and explicit <code>verbAnswer</code>. Optional <code>hint</code> is shown as a clue. JSON accepts <code>verbAnswer</code> as a string or array; CSV accepts multiple answers separated by <code>|</code>.</p><div className="import-actions"><label className="button outline file-pick">Choose JSON / CSV<input type="file" accept=".json,.csv,application/json,text/csv" onChange={(event) => { void handleImport(event.target.files?.[0]); event.currentTarget.value = '' }} /></label><button className="text-button" onClick={() => downloadTemplate('json')}>Download JSON example</button><button className="text-button" onClick={() => downloadTemplate('csv')}>Download CSV example</button></div>{importMessage && <p className="import-success" role="status">{importMessage}</p>}{importError && <pre className="import-error" role="alert">{importError}</pre>}</div></details>
        <div className="selection-tools"><div><p className="eyebrow">Build your practice deck</p><div className="selection-tabs"><button className={selectionMode === 'manual' ? 'selected' : ''} onClick={() => { setSelectionMode('manual'); setSelectionMessage('Choose words from the library below.') }}>Choose manually</button><button className={selectionMode === 'random' ? 'selected' : ''} onClick={() => setSelectionMode('random')}>Random from all words</button></div></div>{selectionMode === 'random' && <div className="random-picks"><span>Pick count</span>{[10, 20, 30, 40, 50, 100].map((count) => <button key={count} onClick={() => sampleRandom(count)}>{count}</button>)}<label>Custom<input type="number" min="1" step="1" value={customCount} onChange={(event) => setCustomCount(event.target.value)} /></label><button className="button dark" onClick={() => sampleRandom(Number(customCount))}>Pick random</button></div>}{selectionMessage && <p className="selection-message" role="status">{selectionMessage}</p>}</div>
        {!cards.length ? <div className="empty"><div className="empty-mark">✳</div><h3>Your first word is waiting</h3><p>Add a word above to start a deck. Include an example sentence to unlock sentence-building practice.</p></div> : <div className="word-list">{cards.map((card) => <article className={`word-row ${selected.includes(card.id) ? 'is-selected' : ''}`} key={card.id}>
          <label className="select-word"><input type="checkbox" checked={selected.includes(card.id)} disabled={selectionMode === "random"} onChange={(e) => setSelected((items) => e.target.checked ? [...items, card.id] : items.filter((id) => id !== card.id))} aria-label={`Select ${card.word}`} /><span className="checkmark">✓</span></label>
          <div className="word-main"><h3>{card.word}</h3><p>{card.meaning}</p>{card.example && <small>“{card.example}”</small>}</div>
          <button className="remove" onClick={() => { setCards((items) => items.filter((item) => item.id !== card.id)); setSelected((items) => items.filter((id) => id !== card.id)) }} aria-label={`Remove ${card.word}`}>×</button>
        </article>)}</div>}
        <div className="practice-bar"><div><p className="eyebrow">Ready when you are</p><strong>{selected.length} {selected.length === 1 ? 'word' : 'words'} selected</strong><p>Pick a practice style to begin.</p></div><div className="practice-actions"><button className="button outline" disabled={selected.length < 2} onClick={() => begin('choice')}><span className="action-icon">◉</span><span><b>Choose an answer</b><small>Multiple choice</small></span><span>→</span></button><button className="button outline" disabled={!selected.length} onClick={() => begin('typing')}><span className="action-icon">⌨</span><span><b>Write an answer</b><small>Recall from memory</small></span><span>→</span></button><button className="button outline" disabled={!cards.some((card) => selected.includes(card.id) && card.example.trim())} onClick={() => begin('sentences')}><span className="action-icon">↔</span><span><b>Build a sentence</b><small>Arrange the words</small></span><span>→</span></button><button className="button outline" disabled={!verbCards.length} onClick={() => begin('verb')}><span className="action-icon">✎</span><span><b>Verb form</b><small>{verbCards.length} cloze exercises</small></span><span>→</span></button></div></div>
      </section>

      {mode !== 'idle' ? mode === 'sentences' ? <section className="exercise" aria-live="polite"><button className="back-link" onClick={() => setMode('idle')}>← Back to library</button><p className="eyebrow">Sentence studio · {questionIndex + 1}</p><h2>Build a sentence with <em>{sentenceWord}</em></h2><p className="exercise-hint">Tap each word in the right order. This sentence uses one of your selected vocabulary examples.</p><div className="sentence-answer">{sentenceAnswer.length ? sentenceAnswer.map((token, i) => <button key={`${token}-${i}`}>{token}</button>) : <span>Your sentence will appear here</span>}</div><div className="token-tray">{sentenceTokens.map((token, i) => <button key={`${token}-${i}`} onClick={() => choose(i)}>{token}</button>)}</div><button className="button dark" disabled={sentenceTokens.length > 0 || !sentenceAnswer.length} onClick={() => sentenceCheck ? next() : setSentenceCheck(cleanSentence(sentenceAnswer.join(" ")) === cleanSentence(sentenceExpected))}>{sentenceCheck === true ? <>Next sentence <span>→</span></> : <>Check sentence <span>✓</span></>}</button>{sentenceCheck !== null && <p className={sentenceCheck ? "result good" : "result bad"}>{sentenceCheck ? "That sentence is in the right order." : "Not quite yet. Start over and try another order."}</p>}<button className="text-button" onClick={resetSentence}>Start over</button></section> : mode === 'verb' ? <section className="exercise" aria-live="polite"><button className="back-link" onClick={() => setMode('idle')}>← Back to library</button><div className="quiz-head"><div><p className="eyebrow">Verb forms · explicit answer key</p><h2>Complete the sentence</h2></div><span className="counter">{questionIndex + 1} / {verbCards.length}<br /><small>{score} correct</small></span></div>{currentVerb ? <><article className="prompt-card"><span>Base verb: <b>{currentVerb.verbBase}</b></span><h3 className="cloze-prompt">{currentVerb.clozeSentence}</h3>{currentVerb.hint && <p className="verb-hint">Clue: {currentVerb.hint}</p>}</article><div className="type-answer"><label htmlFor="verb-answer">Correct verb form</label><div><input id="verb-answer" value={answer} disabled={feedback !== null} onChange={(event) => setAnswer(event.target.value)} onKeyDown={(event) => { if (event.key === 'Enter') feedback === null ? checkVerb() : next() }} placeholder="Type the inflected form…" />{feedback === null ? <button className="button dark" disabled={!answer.trim()} onClick={checkVerb}>Check <span>→</span></button> : <button className="button dark" onClick={next}>Next <span>→</span></button>}</div>{feedback !== null && <><p className={feedback ? 'result good' : 'result bad'}>{feedback ? 'Correct verb form.' : <>Not quite. Expected: <b>{currentVerb.verbAnswer?.join(' / ')}</b></>}</p>{currentVerb.example && <p className="answer-example"><b>Example:</b> {currentVerb.example}</p>}</>}</div></> : <div className="done"><div>✦</div><h2>Practice complete</h2><p>{score} correct out of {verbCards.length}</p><button className="button dark" onClick={() => begin('verb')}>Try again <span>↻</span></button></div>}</section> : <section className="exercise" aria-live="polite"><button className="back-link" onClick={() => setMode('idle')}>← Back to library</button><div className="quiz-head"><div><p className="eyebrow">{mode === 'choice' ? 'Quick check · choose' : 'Quick check · recall'}</p><h2>{mode === 'choice' ? 'Choose the meaning' : 'Write the meaning'}</h2></div><span className="counter">{questionIndex + 1} / {activeCards.length}<br /><small>{score} correct</small></span></div>{current ? <><div className="prompt-card"><span>What does this word mean?</span><h3>{current.word}</h3></div>{mode === 'choice' ? <><div className="answer-options">{choiceOrder.map((id) => cards.find((card) => card.id === id)).filter((card): card is WordCard => !!card).map((card) => <button className={`option ${feedback !== null && card.id === current.id ? 'correct' : ''} ${feedback === false && clean(answer) === clean(card.meaning) ? 'wrong' : ''}`} key={card.id} disabled={feedback !== null} onClick={() => check(card.meaning)}><span>{card.meaning}</span><b>{feedback !== null && card.id === current.id ? '✓' : '↗'}</b></button>)}</div>{feedback !== null && <div className={feedback ? 'feedback-panel correct' : 'feedback-panel incorrect'} role="status"><strong>{feedback ? 'Correct!' : 'Not quite.'}</strong>{!feedback && <p>Expected meaning: {current.meaning}</p>}{current.example && <p><b>Example:</b> {current.example}</p>}</div>}</> : <div className="type-answer"><label htmlFor="meaning-answer">Your answer</label><div><input id="meaning-answer" value={answer} disabled={feedback !== null} onChange={(e) => setAnswer(e.target.value)} onKeyDown={(e) => { if (e.key === 'Enter') feedback === null ? check() : next() }} placeholder="Type the meaning…" />{feedback === null ? <button className="button dark" disabled={!answer.trim()} onClick={() => check()}>Check <span>→</span></button> : <button className="button dark" onClick={next}>Next <span>→</span></button>}</div>{feedback !== null && <><p className={feedback ? 'result good' : 'result bad'}>{feedback ? 'Correct — nice recall.' : `Not quite. Expected meaning: ${current.meaning}`}</p>{current.example && <p className="answer-example"><b>Example:</b> {current.example}</p>}</>}</div>}<div className="quiz-footer"><span>{feedback === null ? 'Take your time — you’ve got this.' : 'Answer checked'}</span>{mode === 'choice' && feedback !== null && <button className="button dark" onClick={next}>Next word <span>→</span></button>}</div></> : <div className="done"><div>✦</div><h2>Practice complete</h2><p>{score} correct out of {activeCards.length}</p><button className="button dark" onClick={() => begin(mode)}>Try again <span>↻</span></button></div>}</section> : null}
    </main>
    <footer><span>wordcraft</span><span>Small steps add up to fluency.</span></footer>
  </div>
}
